package scan

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"os/exec"
	"strings"
)

// toolCmd is one subprocess invocation: the binary and the arguments handed to
// it. Building it is pure, which is what makes the argument surface — the part
// that decides what a scanner is actually asked to do — testable without a
// scanner installed.
//
// It is also what the UI displays. Deriving the shown command and the executed
// one from the same value is the point: the two used to be built separately and
// had drifted (§1.3 D19).
type toolCmd struct {
	Name string
	Args []string
}

// String renders the invocation as a shell command line, for logs and for the
// command the UI shows next to a scan.
func (c toolCmd) String() string {
	if c.Name == "" {
		return ""
	}
	return strings.Join(append([]string{c.Name}, c.Args...), " ")
}

// exitError reports a tool that ran and exited non-zero. The code matters:
// both scanners use a non-zero exit to mean "I found something" rather than
// "I failed" — trivy for vulnerabilities, gitleaks for secrets — so callers
// have to tell the two apart.
type exitError struct {
	Code   int
	Stderr string
}

func (e *exitError) Error() string {
	if e.Stderr != "" {
		return fmt.Sprintf("exit status %d: %s", e.Code, strings.TrimSpace(e.Stderr))
	}
	return fmt.Sprintf("exit status %d", e.Code)
}

// commandRunner is the seam every subprocess in this package passes through.
//
// The package drives trivy and gitleaks as external processes, which makes it
// untestable without both installed and a repository to point them at. Routing
// through this interface lets tests exercise the argument building, the
// exit-code handling and the output parsing — where the defects live — against
// canned output.
type commandRunner interface {
	// Run executes tc and returns what it wrote to stdout. Lines written to
	// stderr are forwarded to progressFn as they arrive, which is how Trivy
	// reports its database download. A tool that runs and exits non-zero
	// returns its stdout along with an *exitError.
	Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error)
}

// cliRunner is the production commandRunner: it shells out to the real tools.
type cliRunner struct{}

func (cliRunner) Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error) {
	cmd := exec.CommandContext(ctx, tc.Name, tc.Args...) //nolint:gosec // name is one of trivy/gitleaks/docker

	var stdout bytes.Buffer
	cmd.Stdout = &stdout

	// Stderr is consumed two ways: streamed to progressFn while the tool runs,
	// and kept so a failure can be reported with the tool's own diagnostic.
	var stderr bytes.Buffer
	if progressFn != nil {
		pipe, err := cmd.StderrPipe()
		if err == nil {
			done := make(chan struct{})
			go func() {
				defer close(done)
				sc := bufio.NewScanner(pipe)
				for sc.Scan() {
					line := strings.TrimSpace(sc.Text())
					if line == "" {
						continue
					}
					stderr.WriteString(line)
					stderr.WriteByte('\n')
					progressFn(line)
				}
				// A read failure on the progress pipe is not a scan failure:
				// the report comes back on stdout, and the tool's exit code
				// says whether it succeeded. Dropping the rest of the progress
				// is the whole consequence.
				_ = sc.Err()
			}()
			if err := cmd.Start(); err != nil {
				return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
			}
			<-done // drain stderr before Wait closes the pipe
			return finish(tc.Name, cmd, &stdout, &stderr)
		}
	}

	cmd.Stderr = &stderr
	if err := cmd.Start(); err != nil {
		return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
	}
	return finish(tc.Name, cmd, &stdout, &stderr)
}

// finish waits for the tool and only then reads what it wrote.
//
// The order is the point, and it is not a style preference: os/exec fills the
// output buffers from goroutines it owns, and only Wait guarantees they are
// done. Reading the buffer in the same expression as Wait — which is what
// `return stdout.Bytes(), waitErr(..., cmd.Wait(), ...)` does, since operands
// are evaluated before the call — snapshots it while it is still empty, and
// every scan comes back with no findings.
func finish(name string, cmd *exec.Cmd, stdout, stderr *bytes.Buffer) ([]byte, error) {
	err := cmd.Wait()
	return stdout.Bytes(), waitErr(name, err, stderr.String())
}

// waitErr turns a non-zero exit into an *exitError carrying the code, and
// leaves anything else (a killed process, a broken pipe) as it is.
func waitErr(name string, err error, stderr string) error {
	if err == nil {
		return nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		if stderr == "" {
			stderr = string(exitErr.Stderr)
		}
		return &exitError{Code: exitErr.ExitCode(), Stderr: stderr}
	}
	return fmt.Errorf("%s failed: %w", name, err)
}

// runner is swapped by tests. Production code never reassigns it, so the
// package stays safe to call concurrently; tests that swap it must not run in
// parallel.
var runner commandRunner = cliRunner{}

package scan

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log"
	"os"
	"os/exec"
	"slices"
	"strconv"
	"strings"
	"testing"
)

// The package drives trivy and gitleaks as subprocesses, so the production
// runner cannot be exercised without both installed. Instead the test binary
// re-executes itself: TestMain notices the helper variables and behaves the way
// a scanner does — a report on stdout, progress on stderr, and an exit code that
// may mean "I found something" rather than "I failed".
const (
	helperMode   = "DEVDESK_SCAN_HELPER"
	helperStdout = "DEVDESK_SCAN_HELPER_STDOUT"
	helperStderr = "DEVDESK_SCAN_HELPER_STDERR"
	helperExit   = "DEVDESK_SCAN_HELPER_EXIT"
	// helperFailOn names an argument the helper refuses. One binary is asked
	// several different things — `docker images` and `docker run` both go to
	// the same fake — so failing has to be selectable per subcommand.
	helperFailOn = "DEVDESK_SCAN_HELPER_FAIL_ON"
)

func TestMain(m *testing.M) {
	if os.Getenv(helperMode) == "1" {
		os.Exit(runAsHelper())
	}
	// Scan logs the command of every stage it starts, which is useful in the
	// application and pure noise across a suite that runs hundreds of them.
	log.SetOutput(io.Discard)
	os.Exit(m.Run())
}

func runAsHelper() int {
	if refused := os.Getenv(helperFailOn); refused != "" && slices.Contains(os.Args[1:], refused) {
		_, _ = fmt.Fprintln(os.Stderr, "cannot connect to the daemon")
		return 1
	}
	if out := os.Getenv(helperStdout); out != "" {
		_, _ = fmt.Fprint(os.Stdout, out)
	}
	if diag := os.Getenv(helperStderr); diag != "" {
		for line := range strings.SplitSeq(diag, "\n") {
			_, _ = fmt.Fprintln(os.Stderr, line)
		}
	}
	code, _ := strconv.Atoi(os.Getenv(helperExit))
	return code
}

// asScanner points a toolCmd at the test binary and tells it what to produce.
func asScanner(t *testing.T, stdout, stderr string, exit int) toolCmd {
	t.Helper()
	self, err := os.Executable()
	if err != nil {
		t.Fatalf("locating the test binary: %v", err)
	}
	t.Setenv(helperMode, "1")
	t.Setenv(helperStdout, stdout)
	t.Setenv(helperStderr, stderr)
	t.Setenv(helperExit, strconv.Itoa(exit))
	t.Setenv(helperFailOn, "")
	return toolCmd{Name: self}
}

// ── The production runner ────────────────────────────────────────────────────

// production is the real runner, named so the tests below can call it in an if
// statement — a composite literal cannot appear there unparenthesised.
var production = cliRunner{}

func TestTheReportOnStdoutIsWhatComesBack(t *testing.T) {
	tc := asScanner(t, `{"Results":[]}`, "", 0)

	stdout, err := production.Run(context.Background(), tc, nil)
	if err != nil {
		t.Fatalf("a tool that exited cleanly was reported as failing: %v", err)
	}
	if string(stdout) != `{"Results":[]}` {
		t.Errorf("stdout = %q, want the report", stdout)
	}
}

// Trivy reports its database download on stderr while it runs, which is the
// only thing the user has to look at during a long scan.
func TestStderrIsHandedOverLineByLine(t *testing.T) {
	tc := asScanner(t, "", "downloading db\n25%\ndone", 0)

	var progress []string
	if _, err := production.Run(context.Background(), tc, func(line string) {
		progress = append(progress, line)
	}); err != nil {
		t.Fatalf("Run: %v", err)
	}

	want := []string{"downloading db", "25%", "done"}
	if strings.Join(progress, "|") != strings.Join(want, "|") {
		t.Errorf("progress = %v, want %v", progress, want)
	}
}

// A blank line is not progress; forwarding it would blank the detail already on
// screen for no reason.
func TestABlankStderrLineIsNotProgress(t *testing.T) {
	tc := asScanner(t, "", "first\n\nsecond", 0)

	var progress []string
	if _, err := production.Run(context.Background(), tc, func(line string) {
		progress = append(progress, line)
	}); err != nil {
		t.Fatalf("Run: %v", err)
	}

	if len(progress) != 2 {
		t.Errorf("progress = %v, want the blank line dropped", progress)
	}
}

// Both scanners exit non-zero to say they found something, so the code has to
// survive alongside the report rather than replace it.
func TestANonZeroExitKeepsBothTheCodeAndTheReport(t *testing.T) {
	tc := asScanner(t, `{"Results":[]}`, "1 vulnerability found", 1)

	stdout, err := production.Run(context.Background(), tc, func(string) {})

	var exit *exitError
	if !errors.As(err, &exit) {
		t.Fatalf("err = %v, want an *exitError", err)
	}
	if exit.Code != 1 {
		t.Errorf("exit code = %d, want 1", exit.Code)
	}
	if !strings.Contains(exit.Stderr, "1 vulnerability found") {
		t.Errorf("the tool's own diagnostic was dropped: %q", exit.Stderr)
	}
	if string(stdout) != `{"Results":[]}` {
		t.Errorf("the report was discarded along with the exit code: %q", stdout)
	}
}

// Nobody watching progress must not mean nobody keeping the diagnostic: it is
// what explains the failure once the scan is over.
func TestTheDiagnosticIsKeptWithNoProgressCallback(t *testing.T) {
	tc := asScanner(t, "", "FATAL unable to initialize scanner", 2)

	_, err := production.Run(context.Background(), tc, nil)

	var exit *exitError
	if !errors.As(err, &exit) {
		t.Fatalf("err = %v, want an *exitError", err)
	}
	if !strings.Contains(exit.Stderr, "unable to initialize scanner") {
		t.Errorf("the diagnostic was lost: %q", exit.Stderr)
	}
}

func TestAToolThatIsNotInstalledIsReportedAsSuch(t *testing.T) {
	_, err := production.Run(context.Background(), toolCmd{Name: "devdesk-no-such-scanner"}, nil)

	if err == nil {
		t.Fatal("a missing binary was reported as a clean run")
	}
	if !strings.Contains(err.Error(), "failed to start") {
		t.Errorf("err = %v, want it to say the tool never started", err)
	}
	// A tool that never ran has no exit code, so it must not look like a
	// scanner reporting findings.
	var exit *exitError
	if errors.As(err, &exit) {
		t.Errorf("a missing binary was reported as an exit code: %v", exit)
	}
}

func TestACancelledScanStops(t *testing.T) {
	tc := asScanner(t, "", "", 0)
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	if _, err := production.Run(ctx, tc, nil); err == nil {
		t.Error("a cancelled scan reported success")
	}
}

// ── Exit handling, on its own ────────────────────────────────────────────────

func TestWaitErrLeavesAFailureThatIsNotAnExitAlone(t *testing.T) {
	err := waitErr("trivy", errors.New("broken pipe"), "")

	if err == nil {
		t.Fatal("a failure was swallowed")
	}
	var exit *exitError
	if errors.As(err, &exit) {
		t.Fatalf("a non-exit failure was turned into an exit code: %v", exit)
	}
	if !strings.Contains(err.Error(), "trivy failed") {
		t.Errorf("err = %v, want the tool named", err)
	}
}

// A caller that let os/exec capture the output — rather than streaming it —
// gets the diagnostic hung on the exit error instead, and that is where it has
// to be read from. This is the path CheckDependencies takes with Output().
func TestTheDiagnosticIsTakenFromTheExitErrorWhenNothingWasCaptured(t *testing.T) {
	tc := asScanner(t, "", "FATAL could not read config", 2)

	_, err := exec.Command(tc.Name).Output() //nolint:gosec // the test binary, acting as a scanner

	got := waitErr("trivy", err, "")
	var exit *exitError
	if !errors.As(got, &exit) {
		t.Fatalf("err = %v, want an *exitError", got)
	}
	if !strings.Contains(exit.Stderr, "could not read config") {
		t.Errorf("the diagnostic was lost: %q", exit.Stderr)
	}
}

func TestWaitErrReportsNothingWhenTheToolSucceeded(t *testing.T) {
	if err := waitErr("trivy", nil, "some noise on stderr"); err != nil {
		t.Errorf("a clean exit was reported as %v", err)
	}
}

func TestAnExitErrorQuotesTheDiagnosticWhenThereIsOne(t *testing.T) {
	withDiag := (&exitError{Code: 2, Stderr: "  config not found\n"}).Error()
	if !strings.Contains(withDiag, "exit status 2") || !strings.Contains(withDiag, "config not found") {
		t.Errorf("Error() = %q, want the code and the diagnostic", withDiag)
	}
	if strings.HasSuffix(withDiag, "\n") {
		t.Errorf("Error() = %q, want the diagnostic trimmed", withDiag)
	}

	if bare := (&exitError{Code: 1}).Error(); bare != "exit status 1" {
		t.Errorf("Error() = %q, want just the code", bare)
	}
}

// ── The invocation as the user sees it ───────────────────────────────────────

func TestAnUnbuiltCommandRendersAsNothing(t *testing.T) {
	if got := (toolCmd{}).String(); got != "" {
		t.Errorf("String() = %q, want empty for a command that was never built", got)
	}
	if got := (toolCmd{Args: []string{"fs"}}).String(); got != "" {
		t.Errorf("String() = %q, want empty when there is no binary to run", got)
	}
}

func TestACommandRendersAsAShellLine(t *testing.T) {
	got := toolCmd{Name: "trivy", Args: []string{"fs", "--format", "json", "/repos"}}.String()
	if got != "trivy fs --format json /repos" {
		t.Errorf("String() = %q", got)
	}
}

package scan

import (
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

// Detection probes the machine it runs on, which is exactly what a test must
// not do. Instead the tools are installed on a PATH of the test's own making:
// each one is a copy of the test binary, which already knows how to behave as a
// scanner (see run_test.go).

// installTools puts the named tools on an otherwise empty PATH and makes them
// answer with output. An empty output is a tool that prints nothing, which is
// how "docker has no such image" is expressed.
func installTools(t *testing.T, output string, names ...string) {
	t.Helper()

	self, err := os.Executable()
	if err != nil {
		t.Fatalf("locating the test binary: %v", err)
	}
	body, err := os.ReadFile(self)
	if err != nil {
		t.Fatalf("reading the test binary: %v", err)
	}

	dir := t.TempDir()
	for _, name := range names {
		if runtime.GOOS == "windows" {
			name += ".exe"
		}
		if err := os.WriteFile(filepath.Join(dir, name), body, 0o755); err != nil {
			t.Fatalf("installing %s: %v", name, err)
		}
	}

	t.Setenv("PATH", dir)
	t.Setenv(helperMode, "1")
	t.Setenv(helperStdout, output)
	t.Setenv(helperStderr, "")
	t.Setenv(helperExit, "0")
}

// A tool installed natively is preferred over the container: it starts faster
// and needs no daemon.
func TestAToolOnThePathIsUsedDirectly(t *testing.T) {
	installTools(t, "Version: 0.50.1", "trivy", "gitleaks")

	deps := CheckDependenciesWithImages("", "")

	if !deps.TrivyAvailable || deps.TrivySource != ToolSourceBinary {
		t.Errorf("trivy: available=%v source=%q, want an installed binary", deps.TrivyAvailable, deps.TrivySource)
	}
	if !deps.GitleaksAvailable || deps.GitleaksSource != ToolSourceBinary {
		t.Errorf("gitleaks: available=%v source=%q, want an installed binary", deps.GitleaksAvailable, deps.GitleaksSource)
	}
	if !strings.Contains(deps.TrivyVersion, "0.50.1") || !strings.Contains(deps.GitleaksVersion, "0.50.1") {
		t.Errorf("versions = %q / %q, want what the tools reported", deps.TrivyVersion, deps.GitleaksVersion)
	}
	// Nothing else is on this PATH.
	if deps.DockerAvailable {
		t.Error("docker was reported as available although it is not installed")
	}
}

// With no binary, the image is the fallback — but only if it has been pulled,
// since scanning must not silently trigger a download.
func TestWithNoBinaryTheDockerImageIsTheFallback(t *testing.T) {
	installTools(t, "sha256:2b1cbf1a4f0e", "docker")

	deps := CheckDependenciesWithImages("", "")

	if !deps.TrivyAvailable || deps.TrivySource != ToolSourceDocker {
		t.Errorf("trivy: available=%v source=%q, want the image", deps.TrivyAvailable, deps.TrivySource)
	}
	if !deps.GitleaksAvailable || deps.GitleaksSource != ToolSourceDocker {
		t.Errorf("gitleaks: available=%v source=%q, want the image", deps.GitleaksAvailable, deps.GitleaksSource)
	}
	if !deps.DockerAvailable {
		t.Error("docker is on the PATH but was not reported as available")
	}
	if !strings.HasPrefix(deps.TrivyVersion, "docker:") {
		t.Errorf("TrivyVersion = %q, want it marked as coming from the image", deps.TrivyVersion)
	}
}

// `docker images -q` printing nothing is how Docker says the image is not
// there. A scan that assumed otherwise would fail at the worst moment.
func TestAnImageThatWasNeverPulledIsNotAvailable(t *testing.T) {
	installTools(t, "", "docker")

	deps := CheckDependenciesWithImages("", "")

	if !deps.DockerAvailable {
		t.Error("docker is on the PATH but was not reported as available")
	}
	if deps.TrivyAvailable || deps.GitleaksAvailable {
		t.Errorf("a tool was reported available with neither a binary nor an image: %+v", deps)
	}
	if deps.TrivySource != ToolSourceNone || deps.GitleaksSource != ToolSourceNone {
		t.Errorf("sources = %q / %q, want none", deps.TrivySource, deps.GitleaksSource)
	}
}

// Docker installed is not Docker running. When the daemon cannot be reached the
// image lookup fails outright, which is not the same as the image being absent
// — but it has the same consequence, and reporting the tool as available would
// mean failing later instead of now.
func TestADaemonThatCannotBeReachedLeavesTheToolsUnavailable(t *testing.T) {
	installTools(t, "sha256:2b1cbf1a4f0e", "docker")
	t.Setenv(helperFailOn, "images")

	deps := CheckDependenciesWithImages("", "")

	if !deps.DockerAvailable {
		t.Error("the docker binary is installed and should be reported as such")
	}
	if deps.TrivyAvailable || deps.GitleaksAvailable {
		t.Errorf("a tool was reported available although the daemon did not answer: %+v", deps)
	}
}

// Failing to read a version is not failing to scan, so the tool stays usable
// and the version simply says where it comes from.
func TestAnImageThatWillNotReportItsVersionIsStillUsable(t *testing.T) {
	installTools(t, "sha256:2b1cbf1a4f0e", "docker")
	t.Setenv(helperFailOn, "run")

	deps := CheckDependenciesWithImages("", "")

	if !deps.TrivyAvailable || deps.TrivySource != ToolSourceDocker {
		t.Errorf("trivy: available=%v source=%q, want the image", deps.TrivyAvailable, deps.TrivySource)
	}
	if deps.TrivyVersion != "docker" || deps.GitleaksVersion != "docker" {
		t.Errorf("versions = %q / %q, want them to fall back to naming the source",
			deps.TrivyVersion, deps.GitleaksVersion)
	}
}

func TestWithNothingInstalledNothingIsAvailable(t *testing.T) {
	installTools(t, "")

	deps := CheckDependenciesWithImages("", "")

	if deps.TrivyAvailable || deps.GitleaksAvailable || deps.DockerAvailable {
		t.Errorf("something was reported available on an empty PATH: %+v", deps)
	}
	// The images are still named, because the dashboard shows which one a scan
	// would use once Docker is there.
	if deps.TrivyImage != DefaultTrivyImage || deps.GitleaksImage != DefaultGitleaksImage {
		t.Errorf("images = %q / %q, want the defaults filled in", deps.TrivyImage, deps.GitleaksImage)
	}
}

func TestConfiguredImagesReplaceTheDefaults(t *testing.T) {
	installTools(t, "")

	deps := CheckDependenciesWithImages("mirror.local/trivy:0.50", "mirror.local/gitleaks:8.18")

	if deps.TrivyImage != "mirror.local/trivy:0.50" || deps.GitleaksImage != "mirror.local/gitleaks:8.18" {
		t.Errorf("images = %q / %q, want the configured ones", deps.TrivyImage, deps.GitleaksImage)
	}
}

// NewScanner is the constructor the application uses, and the only difference
// from the one the tests use is that it probes the machine.
func TestNewScannerDetectsWhatIsInstalled(t *testing.T) {
	installTools(t, "Version: 0.50.1", "trivy", "gitleaks")

	s := NewScanner(ScanOptions{EnableVuln: true})

	if !s.deps.TrivyAvailable || s.deps.TrivySource != ToolSourceBinary {
		t.Errorf("the constructor did not pick up the installed trivy: %+v", s.deps)
	}
	if !s.options.EnableVuln {
		t.Error("the options were not carried onto the scanner")
	}
}

package command

import (
	"strings"
)

// ViewType représente le type de vue
type ViewType string

const (
	ViewDashboard      ViewType = "dashboard"
	ViewStatus         ViewType = "status"
	ViewGitlabAuth     ViewType = "gitlab-auth"
	ViewGitlabExplorer ViewType = "gitlab-explorer"
	ViewWorkspaces     ViewType = "workspaces"
	ViewSecurity       ViewType = "security"
	ViewContainers     ViewType = "containers"
	ViewOCIResources   ViewType = "oci-resources"
	ViewNet            ViewType = "net"
)

// CommandType représente le type de commande
type CommandType string

const (
	CommandView    CommandType = "view"
	CommandContext CommandType = "context"
	CommandTheme   CommandType = "theme"
	CommandQuit    CommandType = "quit"
	CommandUnknown CommandType = "unknown"
)

// Command représente une commande parsée
type Command struct {
	Type CommandType
	View ViewType // Pour les commandes view
	Args []string // Pour les commandes context
}

// ParseCommand analyse une commande et retourne un Command structuré
func ParseCommand(input string) Command {
	// Nettoyer l'input
	cmd := strings.TrimSpace(input)
	cmd = strings.TrimPrefix(cmd, ":")
	cmd = strings.ToLower(cmd)

	// Séparer en parties
	parts := strings.Fields(cmd)
	if len(parts) == 0 {
		return Command{Type: CommandUnknown}
	}

	mainCmd := parts[0]
	args := parts[1:]

	// Vérifier les commandes quit
	if mainCmd == "quit" || mainCmd == "q" {
		return Command{Type: CommandQuit}
	}

	// Vérifier les commandes context
	if mainCmd == "context" || mainCmd == "ctx" || mainCmd == "c" {
		return Command{
			Type: CommandContext,
			Args: args,
		}
	}

	// Vérifier les commandes theme
	if mainCmd == "theme" {
		return Command{
			Type: CommandTheme,
			Args: args,
		}
	}

	// Vérifier les commandes de vue
	viewMap := map[string]ViewType{
		"dashboard":       ViewDashboard,
		"dash":            ViewDashboard,
		"d":               ViewDashboard,
		"status":          ViewStatus,
		"s":               ViewStatus,
		"gitlab-auth":     ViewGitlabAuth,
		"gla":             ViewGitlabAuth,
		"gitlab-explorer": ViewGitlabExplorer,
		"explorer":        ViewGitlabExplorer,
		"exp":             ViewGitlabExplorer,
		"workspaces":      ViewWorkspaces,
		"ws":              ViewWorkspaces,
		"security":        ViewSecurity,
		"sec":             ViewSecurity,
		"containers":      ViewContainers,
		"cont":            ViewContainers,
		"ct":              ViewContainers,
		"oci-resources":   ViewOCIResources,
		"oci":             ViewOCIResources,
		"net":             ViewNet,
	}

	if view, ok := viewMap[mainCmd]; ok {
		return Command{
			Type: CommandView,
			View: view,
		}
	}

	return Command{Type: CommandUnknown}
}

// Parse analyse une commande saisie en mode commande (backward compatible)
// Retourne le ViewType correspondant ou une erreur
func Parse(input string) (ViewType, error) {
	// Nettoyer l'input
	cmd := strings.TrimSpace(input)
	cmd = strings.TrimPrefix(cmd, ":")
	cmd = strings.ToLower(cmd)

	// Mapping des commandes vers les vues
	commands := map[string]ViewType{
		"dashboard":       ViewDashboard,
		"status":          ViewStatus,
		"gitlab-auth":     ViewGitlabAuth,
		"gitlab-explorer": ViewGitlabExplorer,
		"workspaces":      ViewWorkspaces,
		"security":        ViewSecurity,

		// Aliases
		"dash":          ViewDashboard,
		"d":             ViewDashboard,
		"s":             ViewStatus,
		"gla":           ViewGitlabAuth,
		"explorer":      ViewGitlabExplorer,
		"exp":           ViewGitlabExplorer,
		"ws":            ViewWorkspaces,
		"sec":           ViewSecurity,
		"containers":    ViewContainers,
		"cont":          ViewContainers,
		"ct":            ViewContainers,
		"oci-resources": ViewOCIResources,
		"oci":           ViewOCIResources,
		"net":           ViewNet,
	}

	if view, ok := commands[cmd]; ok {
		return view, nil
	}

	// Commande non reconnue, retourner une vue vide
	return "", nil
}

// GetAliases retourne les alias disponibles
func GetAliases() map[string]string {
	return map[string]string{
		"dash":     "dashboard",
		"d":        "dashboard",
		"s":        "status",
		"gla":      "gitlab-auth",
		"explorer": "gitlab-explorer",
