	engine := NewCompletionEngine()

	// Test lowercase, uppercase, mixed case
	inputs := []string{"s", "S", "St", "ST", "status", "STATUS"}

	for _, input := range inputs {
		suggestions := engine.GetSuggestions(input)
		if len(suggestions) == 0 {
