package command

import (
	"testing"
)

func TestParse_AllValidCommands(t *testing.T) {
	// Vérifier que toutes les commandes valides fonctionnent
	tests := []struct {
		name     string
		input    string
		expected ViewType
	}{
		{"status", "status", ViewStatus},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := Parse(tt.input)
			if err != nil {
				t.Errorf("Parse() error = %v", err)
				return
			}
			if result != tt.expected {
				t.Errorf("Parse() = %v, want %v", result, tt.expected)
			}
		})
	}
}

func TestParseCommand_Theme(t *testing.T) {
	tests := []struct {
		name         string
		input        string
		expectedType CommandType
		expectedArgs []string
	}{
		{"theme no args", "theme", CommandTheme, nil},
		{"theme with args ignored", "theme something", CommandTheme, []string{"something"}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := ParseCommand(tt.input)
			if result.Type != tt.expectedType {
				t.Errorf("ParseCommand(%q).Type = %v, want %v", tt.input, result.Type, tt.expectedType)
			}
			if tt.expectedArgs != nil {
				if len(result.Args) != len(tt.expectedArgs) {
					t.Errorf("ParseCommand(%q).Args len = %d, want %d", tt.input, len(result.Args), len(tt.expectedArgs))
					return
				}
				for i, arg := range tt.expectedArgs {
					if result.Args[i] != arg {
						t.Errorf("ParseCommand(%q).Args[%d] = %q, want %q", tt.input, i, result.Args[i], arg)
					}
				}
			}
		})
	}
}

func TestGetAliases(t *testing.T) {
	aliases := GetAliases()

	// Vérifier que gle est dans les alias
	if aliases["s"] != "status" {
		t.Errorf("GetAliases() should include gle -> gitlab-explorer, got: %s", aliases["gle"])
	}
}

func TestParse_Netdiag(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected ViewType
	}{
		// The view is called netdiag everywhere — the directory, the docs, the
		// command list — but only "net" parsed, and ":netdiag" fell through to
		// CommandUnknown with no diagnostic (§1.3 D16).
		{"full name", "netdiag", ViewNetdiag},
		{"net alias", "net", ViewNetdiag},
		{"net with colon prefix", ":net", ViewNetdiag},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := Parse(tt.input)
			if err != nil {
				t.Errorf("Parse() error = %v", err)
				return
			}
			if result != tt.expected {
				t.Errorf("Parse() = %v, want %v", result, tt.expected)
			}
		})
	}
}

func TestParseCommand_Netdiag(t *testing.T) {
	tests := []struct {
		name         string
		input        string
		expectedType CommandType
		expectedView ViewType
	}{
		{"net command", "net", CommandView, ViewNetdiag},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := ParseCommand(tt.input)
			if result.Type != tt.expectedType {
				t.Errorf("ParseCommand(%q).Type = %v, want %v", tt.input, result.Type, tt.expectedType)
			}
			if result.View != tt.expectedView {
				t.Errorf("ParseCommand(%q).View = %v, want %v", tt.input, result.View, tt.expectedView)
			}
		})
	}
}

package command

import (
	"maps"
	"strings"
)

// ViewType représente le type de vue
type ViewType string

const (
	ViewDashboard      ViewType = "dashboard"
	ViewStatus         ViewType = "status"
	ViewGitlabAuth     ViewType = "gitlab-auth"
	ViewGitlabExplorer ViewType = "gitlab-explorer"
	ViewWorkspaces     ViewType = "workspaces"
	ViewSecurity       ViewType = "security"
	ViewContainers     ViewType = "containers"
	ViewOCIResources   ViewType = "oci-resources"
	ViewNetdiag        ViewType = "netdiag"
)

// CommandType représente le type de commande
type CommandType string

const (
	CommandView    CommandType = "view"
	CommandContext CommandType = "context"
	CommandTheme   CommandType = "theme"
	CommandQuit    CommandType = "quit"
	CommandUnknown CommandType = "unknown"
)

// Command représente une commande parsée
type Command struct {
	Type CommandType
	View ViewType // Pour les commandes view
	Args []string // Pour les commandes context
}

// viewNames maps every accepted spelling to the view it names. The key equal to
// the ViewType is its full name; every other key is an alias.
//
// This map is the single source for both parsing and completion. They used to
// be separate lists and had drifted: four views could be typed in full but not
// tab-completed, and `netdiag` was documented everywhere while only `net`
// parsed (§1.3 D16, D17).
var viewNames = map[string]ViewType{
	"dashboard":       ViewDashboard,
	"dash":            ViewDashboard,
	"d":               ViewDashboard,
	"status":          ViewStatus,
	"s":               ViewStatus,
	"gitlab-auth":     ViewGitlabAuth,
	"gla":             ViewGitlabAuth,
	"gitlab-explorer": ViewGitlabExplorer,
	"gle":             ViewGitlabExplorer,
	"explorer":        ViewGitlabExplorer,
	"exp":             ViewGitlabExplorer,
	"workspaces":      ViewWorkspaces,
	"ws":              ViewWorkspaces,
	"w":               ViewWorkspaces,
	"security":        ViewSecurity,
	"sec":             ViewSecurity,
	"containers":      ViewContainers,
	"cont":            ViewContainers,
	"ct":              ViewContainers,
	"oci-resources":   ViewOCIResources,
	"oci":             ViewOCIResources,
	"netdiag":         ViewNetdiag,
	"net":             ViewNetdiag,
}

// actionNames are the commands that do not name a view. They take arguments
// (`context work`, `theme mocha`) or none at all (`quit`).
var actionNames = map[string]CommandType{
	"context": CommandContext,
	"theme":   CommandTheme,
	"quit":    CommandQuit,
}

// actionAliases maps a short form to the full command in actionNames. Kept
// apart from viewNames because completion displays the two differently.
var actionAliases = map[string]string{
	"ctx": "context",
	"c":   "context",
	"q":   "quit",
}

// normalize strips the leading colon and the case, so `:Status ` and `status`
// are the same command.
func normalize(input string) string {
	return strings.ToLower(strings.TrimPrefix(strings.TrimSpace(input), ":"))
}

// ParseCommand analyse une commande et retourne un Command structuré
func ParseCommand(input string) Command {
	parts := strings.Fields(normalize(input))
	if len(parts) == 0 {
		return Command{Type: CommandUnknown}
	}

	mainCmd, args := parts[0], parts[1:]
	if full, isAlias := actionAliases[mainCmd]; isAlias {
		mainCmd = full
	}

	if action, ok := actionNames[mainCmd]; ok {
		if action == CommandQuit {
			return Command{Type: CommandQuit}
		}
		return Command{Type: action, Args: args}
	}

	if view, ok := viewNames[mainCmd]; ok {
		return Command{Type: CommandView, View: view}
	}

	return Command{Type: CommandUnknown}
}

// Parse résout un nom de vue seul, sans les commandes d'action. C'est la forme
// utilisée pour lire `default_view` en configuration.
// Retourne une vue vide, sans erreur, quand le nom n'est pas reconnu.
func Parse(input string) (ViewType, error) {
	if view, ok := viewNames[normalize(input)]; ok {
		return view, nil
	}
	return "", nil
}

// GetAliases retourne chaque alias avec le nom complet qu'il abrège, vues et
// commandes d'action confondues.
func GetAliases() map[string]string {
	aliases := make(map[string]string, len(viewNames)+len(actionAliases))
	for name, view := range viewNames {
		if name != string(view) {
			aliases[name] = string(view)
		}
	}
	maps.Copy(aliases, actionAliases)
	return aliases
}

// FullNames retourne le nom complet de chaque commande — une vue ou une action
// — sans les alias. C'est ce que la complétion propose en premier.
func FullNames() []string {
	names := make([]string, 0, len(viewNames)+len(actionNames))
	for name, view := range viewNames {
		if name == string(view) {
			names = append(names, name)
		}
	}
	for name := range actionNames {
		names = append(names, name)
	}
	return names
}

package security

import (
	"time"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/bubbles/textinput"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ViewState represents the current state of the security view
type ViewState int

const (
	StateInput    ViewState = iota // Form for selecting target and options
	StateScanning                  // Scanning in progress
	StateResults                   // Displaying results summary
	StateDetails                   // Showing detailed findings
)

// Model represents the security scanner view
type Model struct {
	config *config.Config
	width  int
	height int

	state  ViewState
	deps   scan.DependencyStatus
	result *scan.Result
	err    error

	// Form state
	targetType      string
	targetPath      string
	enableVuln      bool
	enableSecret    bool
	enableMisconfig bool
	enableLicense   bool
	generateSBOM    bool
	targetInput     textinput.Model
	focusedField    int

	// Advanced options
	trivyServerInput    textinput.Model
	gitleaksConfigInput textinput.Model
	ignoreUnfixed       bool
	ignoreEOL           bool
	gitleaksHistory     bool

	// Scanning state
	spinner       spinner.Model
	scanStartTime time.Time
	scanStages    []scan.ProgressUpdate    // per-stage progress, in arrival order
	progressCh    chan scan.ProgressUpdate // receives progress updates from scan goroutine
	cancelScan    func()                   // cancels the running scan goroutine; nil when not scanning
	scanGen       int                      // incremented on each startScan; used to discard stale ScanCompleteMsg

	// Results state
	findingsTable    table.Model
	selectedIdx      int
	activeTab        int            // 0=CVE, 1=Secrets, 2=Licenses, 3=Misconfig
	severityFilter   string         // "all", "critical", "high", "medium", "low"
	filteredFindings []scan.Finding // Current filtered findings for display

	// Pre-populated target (from workspace view)
	prefilledTarget string

	// OCI images integration: when true, launching the scan returns to OCI images view
	isImageScan       bool
	returnToOCIImages bool

	// Workspaces integration: when true, scan completion sends result back to workspaces view
	returnToWorkspaces bool

	// OriginView is the view to return to when Esc is pressed in StateResults.
	// Set by the app router when opening this view from workspaces or oci_resources.
	OriginView command.ViewType

	// Status message (temporary feedback)
	statusMessage string

	// Details view scrollable viewport
	detailsViewport viewport.Model

	// Ignore secret confirmation
	confirmModal    *sharedcomponents.ConfirmModal
	findingToIgnore *scan.Finding
}

// New creates a new security scanner view
func New(cfg *config.Config) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	ti := textinput.New()
	ti.Placeholder = "/path/to/scan"
	ti.CharLimit = 256
	ti.Width = 50
	theme.StyleTextInput(&ti)

	// Create findings table
	columns := []table.Column{
		{Title: "Severity", Width: 10},
		{Title: "ID", Width: 20},
		{Title: "Title", Width: 40},
		{Title: "Source", Width: 10},
	}
	t := table.New(
		table.WithColumns(columns),
		table.WithFocused(true),
		table.WithHeight(10),
	)
	t.SetStyles(theme.DefaultTableStyles())

	// Advanced options textinputs
	trivyServer := textinput.New()
	trivyServer.Placeholder = "https://trivy-server:4954"
	trivyServer.CharLimit = 256
	trivyServer.Width = 40
	theme.StyleTextInput(&trivyServer)
	if cfg.Scan.TrivyServer != "" {
		trivyServer.SetValue(cfg.Scan.TrivyServer)
	}

	gitleaksConfig := textinput.New()
	gitleaksConfig.Placeholder = "/path/to/.gitleaks.toml"
	gitleaksConfig.CharLimit = 256
	gitleaksConfig.Width = 40
	theme.StyleTextInput(&gitleaksConfig)

	return Model{
		config:              cfg,
		state:               StateInput,
		targetType:          "directory",
		enableVuln:          cfg.Scan.EnableVuln,
		enableSecret:        cfg.Scan.EnableSecret,
		enableMisconfig:     cfg.Scan.EnableMisconfig,
		enableLicense:       cfg.Scan.EnableLicense,
		generateSBOM:        cfg.Scan.GenerateSBOM,
		ignoreUnfixed:       cfg.Scan.IgnoreUnfixed,
		ignoreEOL:           cfg.Scan.IgnoreEOL,
		gitleaksHistory:     cfg.Scan.GitleaksHistory,
		targetInput:         ti,
		spinner:             s,
		findingsTable:       t,
		focusedField:        0,
		severityFilter:      "all",
		trivyServerInput:    trivyServer,
		gitleaksConfigInput: gitleaksConfig,
	}
}

// NewWithTarget creates a security view pre-populated with a target path
func NewWithTarget(cfg *config.Config, target string) Model {
	m := New(cfg)
	m.prefilledTarget = target
	m.targetPath = target
	m.targetInput.SetValue(target)
	return m
}

// NewWithImageTarget creates a security view pre-populated with an image target.
// Set returnToOCI=true when opened from the OCI images view: launching the scan will send
// the configured options back to OCI images view instead of running the scan in-place.
func NewWithImageTarget(cfg *config.Config, imageName string, returnToOCI bool) Model {
	m := New(cfg)
	m.prefilledTarget = imageName
	m.targetPath = imageName
	m.targetType = "image"
	m.isImageScan = true
	m.returnToOCIImages = returnToOCI
	if imageName == "all" {
		m.targetInput.SetValue("all")
		m.targetInput.Placeholder = "All OCI Images"
	} else {
		m.targetInput.SetValue(imageName)
	}
	return m
}

// NewWithTargetReturnToWorkspaces creates a security view pre-populated with a target path.
// After the scan completes, results are sent back to the workspaces view.
func NewWithTargetReturnToWorkspaces(cfg *config.Config, target string) Model {
	m := NewWithTarget(cfg, target)
	m.returnToWorkspaces = true
	return m
}

// NewWithPreloadedResult creates a security view in StateDetails with a pre-loaded scan result.
// Used to display cached workspace scan results without re-scanning.
func NewWithPreloadedResult(cfg *config.Config, result *scan.Result) Model {
	m := New(cfg)
	m.state = StateResults
	m.result = result
	m.targetPath = result.Target
	m.activeTab = TabCVE
	m.severityFilter = "all"
	// updateFindingsTable will be called when WindowSizeMsg is received
	return m
}

// Init initializes the model
func (m Model) Init() tea.Cmd {
	return tea.Batch(
		m.checkDependencies(),
		m.spinner.Tick,
	)
}

// checkDependencies verifies tool availability
func (m Model) checkDependencies() tea.Cmd {
	trivyImage := m.config.Scan.TrivyImage
	gitleaksImage := m.config.Scan.GitleaksImage
	return func() tea.Msg {
		deps := scan.CheckDependenciesWithImages(trivyImage, gitleaksImage)
		return DepsCheckedMsg{Deps: deps}
	}
}

// InEditMode reports whether a field or a modal has the keyboard, which is what
// stops the router claiming ":", "q" and "?" for itself.
//
// The scanning, results and details states used to be listed here too, for one
// reason: it was the only way to be handed esc. The router forwards esc
// unconditionally now (§1.3 D15), so those states are ordinary again — and get
// the command line, the help overlay and quit back with them.
func (m Model) InEditMode() bool {
	isTextInput := m.state == StateInput && (m.focusedField == 1 || m.focusedField == 7 || m.focusedField == 10)
	return isTextInput || m.confirmModal != nil
}

