package credentials

import (
	"bytes"
	"context"
	"fmt"
	"net/url"
	"os/exec"
	"strings"
	"time"
)

const (
	// credentialUsername is the username DevDesk stores tokens under. GitLab
	// personal access tokens are used as the password of a fixed user.
	credentialUsername = "oauth2"

	// credentialTimeout bounds a `git credential` call. The configured helper
	// may wait for user input, and an unbounded call would freeze the TUI.
	credentialTimeout = 2 * time.Second

	// credentialWaitDelay bounds how long Wait blocks on the output pipes once
	// the process has been killed. Killing git does not kill the helper git
	// spawned, and that surviving grandchild holds the pipes open.
	credentialWaitDelay = 500 * time.Millisecond
)

// GitCredentialStorage stocke les credentials via git credential manager
type GitCredentialStorage struct {
	context string // Contexte DevDesk pour isoler les credentials
}

// NewGitCredentialStorageWithContext crée un GitCredentialStorage context-aware
// Chaque contexte aura ses propres credentials isolés
func NewGitCredentialStorageWithContext(context string) *GitCredentialStorage {
	if context == "" {
		context = "default"
	}
	return &GitCredentialStorage{
		context: context,
	}
}

// describe builds the credential description git reads on stdin. The DevDesk
// context is carried in the path field, which is what keeps two contexts
// pointing at the same host from overwriting each other — see runCredential for
// why that field needs help to survive.
func (g *GitCredentialStorage) describe(urlStr string) (string, error) {
	u, err := url.Parse(urlStr)
	if err != nil {
		return "", fmt.Errorf("invalid URL: %w", err)
	}
	return fmt.Sprintf("protocol=%s\nhost=%s\npath=devdesk/context/%s\nusername=%s\n",
		u.Scheme, u.Host, g.context, credentialUsername), nil
}

// Save sauvegarde un token via git credential
func (g *GitCredentialStorage) Save(urlStr, token string) error {
	desc, err := g.describe(urlStr)
	if err != nil {
		return err
	}
	_, err = runCredential("approve", desc+"password="+token+"\n")
	return err
}

// Load charge un token depuis git credential
func (g *GitCredentialStorage) Load(urlStr string) (string, error) {
	desc, err := g.describe(urlStr)
	if err != nil {
		return "", err
	}
	output, err := runCredential("fill", desc)
	if err != nil {
		return "", err
	}
	if token, ok := parsePassword(output); ok {
		return token, nil
	}
	return "", fmt.Errorf("no credentials found for %s (context: %s)", urlStr, g.context)
}

// Delete supprime un token de git credential
func (g *GitCredentialStorage) Delete(urlStr string) error {
	desc, err := g.describe(urlStr)
	if err != nil {
		return err
	}
	_, err = runCredential("reject", desc)
	return err
}

// parsePassword extracts the password field from a `git credential fill` reply.
func parsePassword(output string) (string, bool) {
	for line := range strings.SplitSeq(output, "\n") {
		if after, ok := strings.CutPrefix(line, "password="); ok {
			return strings.TrimRight(after, "\r"), true
		}
	}
	return "", false
}

// runCredential feeds description to `git credential <op>` and returns its stdout.
//
// credential.useHttpPath is forced on for this invocation only. Git discards the
// path field by default, which would key every credential on protocol://host
// alone and silently collapse all DevDesk contexts onto a single token — the
// last context to authenticate would win for all of them. Setting the option in
// the user's config instead would change how git resolves credentials for every
// repository on the machine, so it is passed per call.
//
// Interactive prompts are disabled: a helper waiting on a terminal DevDesk does
// not own would hang, and the timeout would be the only thing left to catch it.
func runCredential(op, description string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), credentialTimeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, "git", "-c", "credential.useHttpPath=true", "credential", op)
	cmd.Stdin = strings.NewReader(description)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	cmd.WaitDelay = credentialWaitDelay
	cmd.Env = append(cmd.Environ(),
		"GIT_TERMINAL_PROMPT=0", // Désactive les prompts interactifs
		"GCM_INTERACTIVE=never", // Git Credential Manager en mode non-interactif
	)

	err := cmd.Run()
	if ctx.Err() != nil {
		return "", fmt.Errorf("git credential %s timed out (not configured or waiting for input)", op)
	}
	if err != nil {
		return "", fmt.Errorf("git credential %s failed: %v: %s", op, err, strings.TrimSpace(stderr.String()))
	}
	return stdout.String(), nil
}

package auth

import (
	"log"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	gitlabclient "gitlab.com/gitlab-org/api/client-go"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// SaveOption représente les options de sauvegarde du token
const (
	SaveToHelper = iota // Sauvegarder dans Git Credential Manager (sécurisé)
	SaveToConfig        // Sauvegarder dans le fichier de config (moins sécurisé)
)

// Model représente la vue d'authentification GitLab
type Model struct {
	config     *config.Config
	urlInput   textinput.Model
	tokenInput textinput.Model
	storage    credentials.Storage

	currentField int
	saveOption   int // SaveToHelper ou SaveToConfig

	authenticated bool               // True si l'utilisateur est authentifié
	user          *gitlabclient.User // Utilisateur actuellement authentifié

	authenticating bool
	spinner        spinner.Model
	error          string
	success        string
	warning        string // Warning non-bloquant (ex: échec sauvegarde credentials)

	width  int
	height int
}

// New crée une nouvelle vue d'authentification
func New(cfg *config.Config, storage credentials.Storage) *Model {
	// Créer les inputs
	urlInput := textinput.New()
	urlInput.Placeholder = "https://gitlab.com"
	urlInput.CharLimit = 200
	urlInput.Width = 60
	theme.StyleTextInput(&urlInput)

	// Pré-remplir avec la config si disponible
	if cfg.GitLab.URL != "" {
		urlInput.SetValue(cfg.GitLab.URL)
	}

	tokenInput := textinput.New()
	tokenInput.Placeholder = "glpat-xxxxxxxxxxxxxxxxxxxx"
	tokenInput.CharLimit = 100
	tokenInput.Width = 60
	tokenInput.EchoMode = textinput.EchoPassword
	tokenInput.EchoCharacter = '•'
	theme.StyleTextInput(&tokenInput)

	// Spinner
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	// Focus sur le premier champ
	urlInput.Focus()

	return &Model{
		config:         cfg,
		urlInput:       urlInput,
		tokenInput:     tokenInput,
		storage:        storage,
		currentField:   0,
		saveOption:     SaveToHelper, // Par défaut, sauvegarder dans le helper
		authenticating: false,
		spinner:        sp,
		error:          "",
		success:        "",
	}
}

// Init initialise le modèle
func (m *Model) Init() tea.Cmd {
	// Essayer de charger les credentials sauvegardés
	return tea.Batch(
		textinput.Blink,
		m.loadSavedCredentials(),
	)
}

// loadSavedCredentials tente de charger les credentials depuis config ou storage
func (m *Model) loadSavedCredentials() tea.Cmd {
	return func() tea.Msg {
		log.Printf("AUTH: loadSavedCredentials() called")

		// 1. Essayer depuis la config
		if m.config.GitLab.URL != "" && m.config.GitLab.Token != "" {
			log.Printf("AUTH: Credentials loaded from config (URL: %s)", m.config.GitLab.URL)
			return CredentialsLoadedMsg{
				URL:    m.config.GitLab.URL,
				Token:  m.config.GitLab.Token,
				Source: "config",
			}
		}

		// 2. Sinon essayer depuis le storage (credential helper)
		if m.storage != nil && m.config.GitLab.URL != "" {
			log.Printf("AUTH: Trying to load token from storage for URL: %s", m.config.GitLab.URL)
			token, err := m.storage.Load(m.config.GitLab.URL)
			if err == nil && token != "" {
				log.Printf("AUTH: Token loaded from storage successfully")
				return CredentialsLoadedMsg{
					URL:    m.config.GitLab.URL,
					Token:  token,
					Source: "storage",
				}
			}
			if err != nil {
				log.Printf("AUTH: Failed to load from storage: %v", err)
			} else {
				log.Printf("AUTH: No token found in storage")
			}
		} else {
			if m.storage == nil {
				log.Printf("AUTH: Storage is nil")
			}
			if m.config.GitLab.URL == "" {
				log.Printf("AUTH: No URL in config")
			}
		}

		// Rien trouvé
		log.Printf("AUTH: No saved credentials found")
		return CredentialsLoadedMsg{}
	}
}

// CredentialsLoadedMsg contient les credentials chargés
type CredentialsLoadedMsg struct {
	URL    string
	Token  string
	Source string // "config" ou "storage" ou vide
}

// SetAuth configure l'authentification depuis l'extérieur (auto-login global)
func (m *Model) SetAuth(client *gitlabclient.Client, user *gitlabclient.User) {
	m.authenticating = false
	m.authenticated = true
	m.user = user
	m.error = ""
	m.success = "✓ Already authenticated as " + user.Username
}

// Messages pour l'authentification

// AuthStartMsg indique le début de l'authentification
type AuthStartMsg struct{}

// AuthResultMsg contient le résultat de l'authentification
type AuthResultMsg struct {
	Client       *gitlabclient.Client
	User         *gitlabclient.User
	Error        error
	SaveWarning  string // Warning si la sauvegarde des credentials a échoué
	SaveToConfig bool
	ConfigToSave *config.Config
}

// LogoutCompleteMsg signale que le logout est terminé
type LogoutCompleteMsg struct{}

package auth

import (
	"log"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"
	gitlabclient "gitlab.com/gitlab-org/api/client-go"

	gitlabpkg "github.com/anthnel/devdesk/internal/gitlab"
)

// GitLabAuthSuccessMsg est le message d'authentification réussie (venant de app.go)
type GitLabAuthSuccessMsg struct {
	Client *gitlabclient.Client
	User   *gitlabclient.User
}

// Update gère les mises à jour
func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height

	case tea.KeyMsg:
		return m.handleKeyMsg(msg)

	case AuthStartMsg:
		m.authenticating = true
		return m, m.spinner.Tick

	case AuthResultMsg:
		return m.handleAuthResult(msg)

	case spinner.TickMsg:
		if m.authenticating {
			m.spinner, cmd = m.spinner.Update(msg)
			return m, cmd
		}

	case CredentialsLoadedMsg:
		return m.handleCredentialsLoaded(msg)

	case GitLabAuthSuccessMsg:
		return m.handleGitLabAuthSuccess(msg)

	case LogoutCompleteMsg:
		return m.handleLogoutComplete()
	}

	return m, nil
}

// handleKeyMsg traite les entrées clavier
func (m *Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.authenticating {
		return m, nil
	}

	switch msg.String() {
	case "down":
		m.nextField()
		return m, nil

	case "up":
		m.prevField()
		return m, nil

	case "enter":
		return m.handleEnterKey()

	case " ":
		return m.handleSpaceKey()

	case "ctrl+s":
		m.saveOption = SaveToHelper
		return m, nil

	case "ctrl+f":
		m.saveOption = SaveToConfig
		return m, nil

	default:
		return m.handleInputUpdate(msg)
	}
}

// handleEnterKey traite la touche Enter selon le champ actif
func (m *Model) handleEnterKey() (tea.Model, tea.Cmd) {
	if m.authenticated {
		return m, m.logout()
	}
	if m.currentField < 2 {
		m.nextField()
		return m, nil
	}
	if m.currentField == 2 {
		m.saveOption = SaveToHelper
		return m, nil
	}
	if m.currentField == 3 {
		m.saveOption = SaveToConfig
		return m, nil
	}
	m.authenticating = true
	return m, tea.Batch(m.spinner.Tick, m.authenticate())
}

// handleSpaceKey traite la touche espace pour les radio buttons
func (m *Model) handleSpaceKey() (tea.Model, tea.Cmd) {
	if m.currentField == 2 {
		m.saveOption = SaveToHelper
		return m, nil
	}
	if m.currentField == 3 {
		m.saveOption = SaveToConfig
		return m, nil
	}
	return m, nil
}

// handleInputUpdate transmet les messages aux inputs actifs
func (m *Model) handleInputUpdate(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.currentField {
	case 0:
		m.urlInput, cmd = m.urlInput.Update(msg)
	case 1:
		m.tokenInput, cmd = m.tokenInput.Update(msg)
	}
	return m, cmd
}

// handleAuthResult traite le résultat d'authentification
func (m *Model) handleAuthResult(msg AuthResultMsg) (tea.Model, tea.Cmd) {
	log.Printf("AUTH: AuthResultMsg received (Error: %v, User: %v)", msg.Error, msg.User != nil)
	m.authenticating = false
	if msg.Error != nil {
		log.Printf("AUTH: Authentication failed: %v", msg.Error)
		m.error = msg.Error.Error()
		m.success = ""
		m.warning = ""
		return m, nil
	}

	log.Printf("AUTH: Authentication successful for user: %s", msg.User.Username)
	m.error = ""
	m.authenticated = true
	m.user = msg.User
	m.success = "✓ Authenticated as " + msg.User.Username
	m.warning = msg.SaveWarning
	m.currentField = 0
	return m, nil
}

// handleCredentialsLoaded traite les credentials chargés depuis le storage
func (m *Model) handleCredentialsLoaded(msg CredentialsLoadedMsg) (tea.Model, tea.Cmd) {
	log.Printf("AUTH: CredentialsLoadedMsg received (URL: %s, Token: %v, Source: %s)",
		msg.URL, msg.Token != "", msg.Source)
	if msg.URL != "" && msg.Token != "" {
		m.urlInput.SetValue(msg.URL)
		m.tokenInput.SetValue(msg.Token)
		log.Printf("AUTH: Starting auto-login")
		m.authenticating = true
		return m, tea.Batch(m.spinner.Tick, m.authenticate())
	}
	log.Printf("AUTH: No credentials to auto-login")
	return m, nil
}

// handleGitLabAuthSuccess traite l'authentification réussie venant de app.go
func (m *Model) handleGitLabAuthSuccess(msg GitLabAuthSuccessMsg) (tea.Model, tea.Cmd) {
	m.authenticating = false
	m.authenticated = true
	m.user = msg.User
	m.error = ""
	m.success = "✓ Already authenticated as " + msg.User.Username
	m.currentField = 0
	return m, nil
}

// handleLogoutComplete réinitialise l'état après logout
func (m *Model) handleLogoutComplete() (tea.Model, tea.Cmd) {
	m.authenticated = false
	m.user = nil
	m.currentField = 0
	m.tokenInput.SetValue("")
	m.config.GitLab.Token = ""
	m.error = ""
	m.warning = ""
	m.success = "✓ Logged out successfully"
	m.urlInput.Focus()
	return m, nil
}

// nextField passe au champ suivant
func (m *Model) nextField() {
	m.currentField++
	if m.currentField > 4 {
		m.currentField = 4
	}

	m.updateFocus()
}

// prevField passe au champ précédent
func (m *Model) prevField() {
	m.currentField--
	if m.currentField < 0 {
		m.currentField = 0
	}

	m.updateFocus()
}

// updateFocus met à jour le focus des champs
func (m *Model) updateFocus() {
	switch m.currentField {
	case 0:
		m.urlInput.Focus()
		m.tokenInput.Blur()
	case 1:
		m.urlInput.Blur()
		m.tokenInput.Focus()
	default:
		// Champs 2, 3, 4 (checkboxes et button) - pas de textinput
		m.urlInput.Blur()
		m.tokenInput.Blur()
	}
}

// authenticate lance l'authentification
func (m *Model) authenticate() tea.Cmd {
	url := m.urlInput.Value()
	token := m.tokenInput.Value()

	if url == "" || token == "" {
		m.error = "URL and token are required"
		return nil
	}

	// Copier les données nécessaires AVANT la goroutine (Rule 110)
	saveToHelper := m.saveOption == SaveToHelper
	saveToConfig := m.saveOption == SaveToConfig
	config := m.config

	// Commande asynchrone
	return func() tea.Msg {
		// Créer l'auth
		auth := gitlabpkg.NewAuth(m.storage)

		// Authentifier avec saveToHelper
		result, err := auth.Authenticate(url, token, saveToHelper)
		if err != nil {
			return AuthResultMsg{
				Client: nil,
				User:   nil,
				Error:  err,
			}
		}

		// Préparer la config à sauvegarder (copie, pas modification du modèle!)
		config.GitLab.URL = url
		if saveToConfig {
			config.GitLab.Token = token
		}

		// Retourner le message avec les données
		return AuthResultMsg{
			Client:       result.Client,
			User:         result.User,
			Error:        nil,
			SaveWarning:  result.SaveWarning,
			SaveToConfig: saveToConfig,
			ConfigToSave: config,
		}
	}
}

// logout déconnecte l'utilisateur
func (m *Model) logout() tea.Cmd {
	url := m.urlInput.Value()
	storage := m.storage

	// Commande asynchrone
	return func() tea.Msg {
		// Créer l'auth
		auth := gitlabpkg.NewAuth(storage)

		// Supprimer les credentials du storage
		_ = auth.Logout(url) // Ignorer l'erreur, on déconnecte quand même

		// NE PAS modifier m.config ici (Rule 110) - le faire dans Update()
		// Retourner le message de logout complet
		return LogoutCompleteMsg{}
	}
}

package auth

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

func (m Model) InEditMode() bool {
	// En mode édition seulement si un textinput a le focus (champs 0 ou 1)
	// et que l'utilisateur n'est pas en train d'authentifier
	// Si authentifié, on n'est plus en mode édition
	if m.authenticated || m.authenticating {
		return false
	}
	// En mode édition si on est sur un des champs de texte
	return m.currentField == 0 || m.currentField == 1
}

func (m Model) GetShortcuts() shortcut.Shortcuts {
	return []shortcut.Shortcut{
		{Key: "enter", Description: "Submit / Advance field"},
		{Key: "space", Description: "Select option"},
		{Key: "ctrl+s", Description: "Toggle save to helper"},
		{Key: "ctrl+f", Description: "Toggle save to config"},
		{Key: "alt+:", Description: "Command mode"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight returns the footer height for this view (Rule 124).
func (m Model) GetFooterHeight() int {
	return 2 // empty line + info line
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
func (m Model) RenderFooter(width int) string {
	return theme.EmptyLineBg(width) + "\n" + theme.EmptyLineBg(width)
}

func (m Model) GetTitle() string {
	return theme.IconUser + " Gitlab Authentication"
}

func (m Model) GetIcon() string {
	return ""
}

// GetHeaderInfo returns the key-value info for the header
func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	return []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
	}
}

// GetHelpContent retourne le contenu d'aide de la vue GitLab Auth
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title:       "GitLab Authentication",
		Description: "This view allows you to connect to a GitLab instance. Once authenticated, you can explore groups and projects, clone repositories, and manage your GitLab resources.",
		KeyBindings: []help.KeyBinding{
			{Key: "↑ / ↓", Description: "Navigate between form fields"},
			{Key: "enter", Description: "Submit form / advance to next field"},
			{Key: "space", Description: "Select save option"},
			{Key: "ctrl+s", Description: "Toggle save to Git Credential Manager"},
			{Key: "ctrl+f", Description: "Toggle save to config file"},
			{Key: "alt+:", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Save Options",
				Body:  "Git Credential Manager (recommended): stores the token securely via Git's credential helper. The token does not appear in configuration files.\n\nConfig file: saves the token in ~/.devdesk/contexts/<context>/config.yaml. Less secure but works without a credential helper.",
			},
			{
				Title: "Personal Access Token",
				Body:  "Create a token in GitLab > Settings > Access Tokens. Required scopes: api, read_user. The token must start with 'glpat-'.",
			},
		},
	}
}

// View rend la vue
func (m *Model) View() string {
	var sections []string

	// Status (only show when not authenticated, to avoid duplication with logged-in view)
	if m.success != "" && !m.authenticated {
		sections = append(sections, m.renderSuccess())
	}

	// Warning (non-bloquant, ex: échec sauvegarde credentials)
	if m.warning != "" {
		sections = append(sections, m.renderWarning())
	}

	// Form
	sections = append(sections, m.renderForm())

	// Error
	if m.error != "" {
		sections = append(sections, m.renderError())
	}

	return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1).Render(strings.Join(sections, "\n"))
}

func (m *Model) renderForm() string {
	var b strings.Builder

	// Spinner si en cours d'authentification
	if m.authenticating {
		b.WriteString(theme.SpinnerMessage(m.spinner.View(), "Authenticating...") + "\n\n")
		return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1, 2).Render(b.String())
	}

	// Si authentifié, afficher la vue "Logged in"
	if m.authenticated && m.user != nil {
		return m.renderLoggedInView()
	}

	// Sinon, afficher le formulaire de login
	// URL
	labelStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Bold(true)
	if m.currentField == 0 {
		labelStyle = labelStyle.Foreground(theme.ColorPrimary)
	}
	b.WriteString(labelStyle.Render("GitLab URL") + "\n")
	b.WriteString(m.urlInput.View() + "\n\n")

	// Token
	labelStyle = lipgloss.NewStyle().Background(theme.ColorBackground).Bold(true)
	if m.currentField == 1 {
		labelStyle = labelStyle.Foreground(theme.ColorPrimary)
	}
	b.WriteString(labelStyle.Render("Personal Access Token") + "\n")
	b.WriteString(m.tokenInput.View() + "\n\n")

	// Options
	b.WriteString(theme.DimStyle.Render("Save options:") + "\n")

	b.WriteString(theme.RenderRadioButton(m.saveOption == SaveToHelper, "Save to Git Credential Manager (secure)", m.currentField == 2) + "\n")
	b.WriteString(theme.RenderRadioButton(m.saveOption == SaveToConfig, "Save token to config file (less secure)", m.currentField == 3) + "\n\n")

	// Button
	b.WriteString(theme.RenderButton("Login", m.currentField == 4, "primary"))

	return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1, 2).Render(b.String())
}

func (m *Model) renderLoggedInView() string {
	var b strings.Builder

	// Afficher les infos de l'utilisateur
	b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Bold(true).Render("Authenticated as: "))
	b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorPrimary).Bold(true).Render(m.user.Username))
	if m.user.Name != "" {
		b.WriteString(theme.Bg(" (" + m.user.Name + ")"))
	}
	b.WriteString("\n")

	// Afficher l'URL GitLab
	if m.config != nil && m.config.GitLab.URL != "" {
		b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Bold(true).Render("GitLab URL: "))
		b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorPrimary).Bold(true).Render(m.config.GitLab.URL) + "\n")
	}
	b.WriteString("\n")

	// Bouton Logout
	b.WriteString(theme.RenderButton("Logout", m.currentField == 0, "danger"))

	return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1, 2).Render(b.String())
}

func (m *Model) renderSuccess() string {
	style := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorOK).
		Padding(1, 2)
	return style.Render(m.success)
}

func (m *Model) renderWarning() string {
	style := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorError).
		Padding(1, 2).
		Width(m.width - 8)
	return style.Render(theme.IconWarning + " " + m.warning)
}

func (m *Model) renderError() string {
	style := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorError).
		Padding(1, 2)
	return style.Render("✗ " + m.error)
}

