11	func TestMemoryStorage(t *testing.T) {
12		storage := NewMemoryStorage()
13	
14		testURL := "https://gitlab.example.com"
15		testToken := "test-token-12345"
16	
17		// Test Save
18		err := storage.Save(testURL, testToken)
19		if err != nil {
20			t.Fatalf("Save() error: %v", err)
21		}
22	
23		// Test Load
24		token, err := storage.Load(testURL)
25		if err != nil {
26			t.Fatalf("Load() error: %v", err)
27		}
28		if token != testToken {
29			t.Errorf("Expected token '%s', got '%s'", testToken, token)
30		}
31	
32		// Test Load non-existent
33		_, err = storage.Load("https://nonexistent.com")
34		if err == nil {
35			t.Error("Expected error when loading non-existent URL, got nil")
36		}
37	
38		// Test Delete
39		err = storage.Delete(testURL)
40		if err != nil {
41			t.Fatalf("Delete() error: %v", err)
42		}
43	
44		// Verify deletion
45		_, err = storage.Load(testURL)
46		if err == nil {
47			t.Error("Expected error after delete, got nil")
48		}
49	}
50	
51	func TestMemoryStorageMultipleURLs(t *testing.T) {
52		storage := NewMemoryStorage()
53	
54		urls := map[string]string{
55			"https://gitlab.com":         "token1",
56			"https://gitlab.example.com": "token2",
57			"https://custom.gitlab.org":  "token3",
58		}
59	
60		// Save multiple
61		for url, token := range urls {
62			if err := storage.Save(url, token); err != nil {
63				t.Fatalf("Save() error for %s: %v", url, err)
64			}
65		}
66	
67		// Load and verify
68		for url, expectedToken := range urls {
69			token, err := storage.Load(url)
70			if err != nil {
71				t.Fatalf("Load() error for %s: %v", url, err)
72			}
73			if token != expectedToken {
74				t.Errorf("Expected token '%s' for %s, got '%s'", expectedToken, url, token)
75			}
76		}
77	
78		// Delete one
79		if err := storage.Delete("https://gitlab.com"); err != nil {
80			t.Fatalf("Delete() error: %v", err)
81		}
82	
83		// Verify others still exist
84		token, err := storage.Load("https://gitlab.example.com")
85		if err != nil {
86			t.Errorf("Load() error after deleting different URL: %v", err)
87		}
88		if token != "token2" {
89			t.Errorf("Expected token 'token2', got '%s'", token)
90		}
91	}
92	
93	func TestFileStorage(t *testing.T) {
94		tmpDir := t.TempDir()
95		filePath := filepath.Join(tmpDir, "credentials.json")
96	
97		storage := NewFileStorage(filePath)
98	
99		testURL := "https://gitlab.example.com"
100		testToken := "test-token-12345"
101	
102		// Test Save
103		err := storage.Save(testURL, testToken)
104		if err != nil {
105			t.Fatalf("Save() error: %v", err)
106		}
107	
108		// Verify file was created
109		if _, err := os.Stat(filePath); os.IsNotExist(err) {
110			t.Fatal("Credentials file was not created")
111		}
112	
113		// Verify file permissions (Unix only — Windows does not support POSIX mode bits)
114		if runtime.GOOS != "windows" {
115			info, err := os.Stat(filePath)
116			if err != nil {
117				t.Fatalf("Stat() error: %v", err)
118			}
119			if mode := info.Mode(); mode.Perm() != 0600 {
120				t.Errorf("Expected file permissions 0600, got %o", mode.Perm())
121			}
122		}
123	
124		// Test Load
125		token, err := storage.Load(testURL)
126		if err != nil {
127			t.Fatalf("Load() error: %v", err)
128		}
129		if token != testToken {
