273	func keysOf(shortcuts shortcut.Shortcuts) string {
274		keys := make([]string, 0, len(shortcuts))
275		for _, s := range shortcuts {
276			keys = append(keys, s.Key)
277		}
278		return strings.Join(keys, ",")
279	}
